import { execute } from './lib/runtime/run-test9.mjs';

const exitCode = execute(process.argv);

if (exitCode !== 0) {
  process.exitCode = exitCode;
}

import { bech32HrpExpand, bech32Polymod } from '../bech32/index.mjs';
import { parseArgs } from '../cli/index.mjs';
import { parseCommaSeparatedIntegers, PythonValueError } from '../data/index.mjs';
import { formatPythonList, formatPythonValueErrorTraceback } from '../format/index.mjs';

function writeOutput(stream, text) {
  stream.write(text);
}

export function execute(argv = process.argv) {
  const parsed = parseArgs(argv);

  if (parsed.kind === 'help') {
    writeOutput(process.stdout, parsed.text);
    return parsed.exitCode;
  }

  if (parsed.kind === 'error') {
    writeOutput(process.stderr, parsed.text);
    return parsed.exitCode;
  }

  try {
    const data = parseCommaSeparatedIntegers(parsed.values.b);
    const hrpExpanded = bech32HrpExpand(parsed.values.a);
    const checksum = bech32Polymod([...hrpExpanded, ...data]);

    writeOutput(process.stdout, `${formatPythonList(hrpExpanded)}\n`);
    writeOutput(process.stdout, `${checksum.toString()}\n`);

    return 0;
  } catch (error) {
    if (error instanceof PythonValueError) {
      writeOutput(process.stderr, formatPythonValueErrorTraceback(error.message));
      return 1;
    }

    throw error;
  }
}

import { buildHelpText, buildParseError, getProgramName } from './messages.mjs';

const NEGATIVE_INTEGER_TOKEN = /^-[0-9](?:_?[0-9])*$/;

function isHelpOption(token) {
  if (token === '-h' || token === '--help') {
    return true;
  }

  return token.startsWith('--') && token.length > 2 && !token.includes('=') && '--help'.startsWith(token);
}

function extractAssignment(token) {
  if (token.startsWith('--a=')) {
    return { name: 'a', value: token.slice(4) };
  }

  if (token.startsWith('--b=')) {
    return { name: 'b', value: token.slice(4) };
  }

  return null;
}

function looksLikeMissingValue(token) {
  if (token === undefined || token === '--') {
    return true;
  }

  if (token === '-' || !token.startsWith('-')) {
    return false;
  }

  return !NEGATIVE_INTEGER_TOKEN.test(token);
}

export function parseArgs(argv = process.argv) {
  const programName = getProgramName(argv);
  const tokens = argv.slice(2);
  let a;
  let b;
  let stopOptionParsing = false;
  const extras = [];

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];

    if (stopOptionParsing) {
      extras.push(token);
      continue;
    }

    if (token === '--') {
      stopOptionParsing = true;
      continue;
    }

    if (isHelpOption(token)) {
      return { kind: 'help', text: buildHelpText(programName), exitCode: 0 };
    }

    const assignment = extractAssignment(token);

    if (assignment !== null) {
      if (assignment.name === 'a') {
        a = assignment.value;
      } else {
        b = assignment.value;
      }

      continue;
    }

    if (token === '--a' || token === '--b') {
      const nextToken = tokens[index + 1];

      if (looksLikeMissingValue(nextToken)) {
        return {
          kind: 'error',
          text: buildParseError(programName, `argument ${token}: expected one argument`),
          exitCode: 2,
        };
      }

      if (token === '--a') {
        a = nextToken;
      } else {
        b = nextToken;
      }

      index += 1;
      continue;
    }

    extras.push(token);
  }

  const missing = [];

  if (a === undefined) {
    missing.push('--a');
  }

  if (b === undefined) {
    missing.push('--b');
  }

  // argparse reports missing required options before unrecognized extras.
  if (missing.length > 0) {
    return {
      kind: 'error',
      text: buildParseError(programName, `the following arguments are required: ${missing.join(', ')}`),
      exitCode: 2,
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      text: buildParseError(programName, `unrecognized arguments: ${extras.join(' ')}`),
      exitCode: 2,
    };
  }

  return {
    kind: 'ok',
    exitCode: 0,
    values: { a, b },
  };
}

function escapeCharacter(character) {
  if (character === '\\') {
    return '\\\\';
  }

  if (character === '\'') {
    return '\\\'';
  }

  if (character === '\n') {
    return '\\n';
  }

  if (character === '\r') {
    return '\\r';
  }

  if (character === '\t') {
    return '\\t';
  }

  const codePoint = character.codePointAt(0);

  if (codePoint < 32 || codePoint === 127) {
    return `\\x${codePoint.toString(16).padStart(2, '0')}`;
  }

  return character;
}

export function renderPythonStringLiteral(value) {
  return `'${[...value].map((character) => escapeCharacter(character)).join('')}'`;
}
